  R(-7,-9,7,1,'#5A3E2A');R(-7,-8,1,8,'#3E2A1C');R(-1,-8,1,8,'#3E2A1C');R(-8,-16,1,8,'#4A3222');
  R(-6,-17,6,8,night?'#B8B39F':'#EDE6D1');R(-6,-17,1,8,night?'#9E9986':'#D6CEB6');R(-1,-16,2,1,night?'#B8B39F':'#EDE6D1');
